settings.custom_css:
/* =========================================================
   RAMIS PREMIUM FOOTER
   Primary  : #006660
   Accent   : #FFCE3A
========================================================= */

selector {
    --primary: #006660;
    --primary-dark: #003f3c;
    --accent: #FFCE3A;
    --text: #ffffff;
    --muted: rgba(255,255,255,0.68);

    position: relative;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 10% 0%,
            rgba(0,102,96,0.55),
            transparent 32%
        ),
        radial-gradient(
            circle at 90% 100%,
            rgba(255,206,58,0.08),
            transparent 30%
        ),
        linear-gradient(
            145deg,
            #003f3c 0%,
            #005550 48%,
            #002f2d 100%
        ) !important;

    border-radius: 28px 28px 0 0;

    box-shadow:
        0 -15px 50px rgba(0, 70, 67, 0.15);

    color: var(--text);
}


/* =========================================================
   افکت نور پس زمینه
========================================================= */

selector::before {
    content: "";
    position: absolute;

    width: 450px;
    height: 450px;

    top: -250px;
    right: -120px;

    border-radius: 50%;

    background: rgba(255,206,58,0.045);

    filter: blur(10px);

    pointer-events: none;
}


/* =========================================================
   تیتر ستون‌ها
========================================================= */

selector .elementor-element-dc0d1bd p,
selector .elementor-element-becc8fd p,
selector .elementor-element-ea27618 p,
selector .elementor-element-67e387f p {

    color: #ffffff !important;

    font-size: 17px !important;
    font-weight: 800 !important;

    margin-bottom: 20px !important;

    position: relative;
}


/* خط طلایی زیر تیتر */

selector .elementor-element-dc0d1bd p::after,
selector .elementor-element-becc8fd p::after,
selector .elementor-element-ea27618 p::after,
selector .elementor-element-67e387f p::after {

    content: "";

    display: block;

    width: 32px;
    height: 3px;

    margin-top: 10px;

    background: var(--accent);

    border-radius: 10px;
}


/* =========================================================
   متن معرفی
========================================================= */

selector .elementor-element-428cc73 p {

    color: var(--muted) !important;

    line-height: 2.1 !important;

    font-size: 14px !important;

    max-width: 360px;

    margin-top: 18px;
}


/* =========================================================
   منوهای فوتر
========================================================= */

selector .elementor-nav-menu {
    padding: 0 !important;
}

selector .elementor-nav-menu li {
    margin: 0 !important;
}

selector .elementor-nav-menu a {

    color: rgba(255,255,255,0.68) !important;

    padding: 7px 0 !important;

    font-size: 14px !important;

    transition:
        color .25s ease,
        transform .25s ease,
        padding .25s ease;
}


/* Hover لینک */

selector .elementor-nav-menu a:hover {

    color: var(--accent) !important;

    padding-right: 7px !important;

    transform: translateX(-4px);
}


/* لینک فعال */

selector .elementor-nav-menu .current-menu-item > a {

    color: var(--accent) !important;
}


/* =========================================================
   بخش ارتباط با ما
========================================================= */

selector .elementor-element-bc8f45a,
selector .elementor-element-c2a88fc,
selector .elementor-element-07c2dee {

    display: flex;

    align-items: center;

    gap: 12px;

    padding: 11px 13px;

    margin-bottom: 9px;

    background: rgba(255,255,255,0.045);

    border: 1px solid rgba(255,255,255,0.07);

    border-radius: 12px;

    transition: all .3s ease;
}


/* Hover کارت ارتباط */

selector .elementor-element-bc8f45a:hover,
selector .elementor-element-c2a88fc:hover,
selector .elementor-element-07c2dee:hover {

    background: rgba(255,255,255,0.09);

    border-color: rgba(255,206,58,0.35);

    transform: translateX(-4px);
}


/* =========================================================
   آیکون‌های تماس
========================================================= */

selector .elementor-element-083943f .elementor-icon,
selector .elementor-element-2ea22e2 .elementor-icon,
selector .elementor-element-2c58493 .elementor-icon {

    width: 38px;
    height: 38px;

    display: flex;

    align-items: center;
    justify-content: center;

    background: rgba(255,206,58,0.12);

    color: var(--accent) !important;

    border-radius: 10px;

    transition: all .3s ease;
}


/* SVG */

selector .elementor-element-083943f svg,
selector .elementor-element-2ea22e2 svg,
selector .elementor-element-2c58493 svg {

    fill: currentColor !important;

    width: 16px;
}


/* Hover آیکون */

selector .elementor-element-bc8f45a:hover .elementor-icon,
selector .elementor-element-c2a88fc:hover .elementor-icon,
selector .elementor-element-07c2dee:hover .elementor-icon {

    background: var(--accent);

    color: #003f3c !important;

    transform: scale(1.08);
}


/* =========================================================
   متن اطلاعات تماس
========================================================= */

selector .elementor-element-278adb3 p,
selector .elementor-element-108ccfa p,
selector .elementor-element-75e5c1c p {

    color: rgba(255,255,255,0.78) !important;

    font-size: 13px !important;

    margin: 0 !important;
}


/* =========================================================
   شبکه‌های اجتماعی
========================================================= */

selector .elementor-social-icons-wrapper {

    display: flex;

    gap: 9px;

    margin-top: 25px;
}


selector .elementor-social-icon {

    width: 40px !important;
    height: 40px !important;

    display: flex !important;

    align-items: center;
    justify-content: center;

    background: rgba(255,255,255,0.07) !important;

    color: rgba(255,255,255,0.8) !important;

    border: 1px solid rgba(255,255,255,0.09);

    border-radius: 12px !important;

    transition: all .3s ease !important;
}


/* Hover شبکه اجتماعی */

selector .elementor-social-icon:hover {

    background: var(--accent) !important;

    color: #003f3c !important;

    border-color: var(--accent);

    transform: translateY(-5px) rotate(-3deg);

    box-shadow:
        0 8px 20px rgba(255,206,58,0.18);
}


/* =========================================================
   خط جداکننده
========================================================= */

selector .elementor-element-ec4aee8 {

    margin-top: 35px;
    margin-bottom: 20px;
}


selector .elementor-divider-separator {

    border-top:
        1px solid rgba(255,255,255,0.10) !important;
}


/* =========================================================
   کپی رایت
========================================================= */

selector .elementor-element-06ffad0 {

    padding-top: 5px;
}


selector .elementor-element-366eb21 p {

    color: rgba(255,255,255,0.45) !important;

    font-size: 12px !important;

    text-align: center;

    margin: 0 !important;
}


/* =========================================================
   لوگو
========================================================= */

selector .elementor-element-f73a4cc img {

    max-width: 190px;

    transition: all .3s ease;
}


selector .elementor-element-f73a4cc img:hover {

    transform: translateY(-2px);
    filter: drop-shadow(0 8px 18px rgba(255,255,255,0.08));
}


/* =========================================================
   موبایل
========================================================= */

@media (max-width: 767px) {

    selector {

        border-radius: 20px 20px 0 0;

        padding-top: 45px !important;
        padding-bottom: 25px !important;
    }

    selector .elementor-element-f73a4cc img {

        max-width: 160px;
    }

    selector .elementor-element-428cc73 p {

        font-size: 13px !important;

        line-height: 2 !important;
    }

    selector .elementor-social-icons-wrapper {

        justify-content: center;
    }

    selector .elementor-element-bc8f45a,
    selector .elementor-element-c2a88fc,
    selector .elementor-element-07c2dee {

        padding: 10px;
    }
}

selector,
selector img {
    background: transparent !important;
    background-color: transparent !important;
}
